//! AC3: `publish` writer -> load -> ACK parity with Python.
//!
//! Expected outcomes are generated by `tests/generate_rust_store_fixture.py`
//! from the REAL `share.broker_host.BrokerHostCoordinator._publish`.

use std::cell::RefCell;
use std::path::PathBuf;
use std::rc::Rc;
use std::sync::{Arc, Mutex};

use serde_json::{json, Value};
use um_broker::error::{BrokerResult, ResultCode};
use um_broker::publish::{InstanceChannel, InstanceRegistry, ProjectionWriter, PublishCoordinator};

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join("tests/fixtures/rust_store_rev1.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[derive(Clone)]
struct FakeWriter {
    calls: Rc<RefCell<Vec<Value>>>,
    fail: bool,
}

impl ProjectionWriter for FakeWriter {
    fn fingerprint(&self, projection: &Value) -> String {
        um_store::fingerprint(projection)
    }

    fn write(
        &mut self,
        _projection: &Value,
        generation: i64,
        fingerprint: &str,
    ) -> Result<(), String> {
        self.calls.borrow_mut().push(json!({
            "write": {"generation": generation, "fingerprint": fingerprint},
        }));
        if self.fail {
            Err("writer refused".to_string())
        } else {
            Ok(())
        }
    }
}

type AfterLoad = Rc<RefCell<Box<dyn FnMut()>>>;

struct FakeChannel {
    calls: Rc<RefCell<Vec<Value>>>,
    queue: Rc<RefCell<Vec<Value>>>,
    after_load: Option<AfterLoad>,
}

impl InstanceChannel for FakeChannel {
    fn call(&mut self, action: &str, fields: &Value, instance_id: &str) -> Result<Value, String> {
        self.calls.borrow_mut().push(json!({
            "instance_call": {
                "action": action,
                "instance_id": instance_id,
                "fields": fields,
            },
        }));
        if let Some(after_load) = &self.after_load {
            (after_load.borrow_mut())();
        }
        let response = self.queue.borrow_mut().remove(0);
        if let Some(message) = response.get("raise").and_then(Value::as_str) {
            return Err(message.to_string());
        }
        Ok(response)
    }
}

#[test]
fn the_publish_chain_matches_python() {
    let fixture = fixture();
    for case in fixture["publish"].as_array().unwrap() {
        let name = case["case"].as_str().unwrap();
        let input = &case["input"];
        let projection = input["projection"].clone();
        let generation = input["generation"].as_i64().unwrap();
        let fingerprint = input["fingerprint"].as_str().unwrap().to_string();
        let terminate_keys: Option<Vec<String>> = input
            .get("terminate_keys")
            .and_then(Value::as_array)
            .map(|keys| {
                keys.iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect()
            });

        let registry = Arc::new(Mutex::new(InstanceRegistry::default()));
        for instance_id in case["instances"].as_array().cloned().unwrap_or_default() {
            registry
                .lock()
                .unwrap()
                .register(instance_id.as_str().unwrap())
                .unwrap();
        }
        let writer_calls = Rc::new(RefCell::new(Vec::new()));
        let channel_calls = Rc::new(RefCell::new(Vec::new()));
        let queue = Rc::new(RefCell::new(
            case["responses"].as_array().cloned().unwrap_or_default(),
        ));
        let discovery_calls = Rc::new(RefCell::new(0usize));

        let after_load = match case["after_load"].as_str() {
            None => None,
            Some(mode) => {
                let mode = mode.to_string();
                let registry = Arc::clone(&registry);
                let fired = Rc::new(RefCell::new(false));
                let instance = case["after_load_instance"].as_str().unwrap().to_string();
                Some(Rc::new(RefCell::new(Box::new(move || {
                    if mode == "once" && *fired.borrow() {
                        return;
                    }
                    *fired.borrow_mut() = true;
                    registry.lock().unwrap().register(instance.clone()).unwrap();
                })
                    as Box<dyn FnMut()>)))
            }
        };
        let mut coordinator = PublishCoordinator::new(
            FakeWriter {
                calls: Rc::clone(&writer_calls),
                fail: case["fail_write"].as_bool().unwrap_or(false),
            },
            FakeChannel {
                calls: Rc::clone(&channel_calls),
                queue,
                after_load,
            },
            Arc::clone(&registry),
        );
        let instances_empty = case["instances"]
            .as_array()
            .map(|instances| instances.is_empty())
            .unwrap_or(true);
        if case["discover"].as_bool().unwrap_or(false) || instances_empty {
            let registry = Arc::clone(&registry);
            let calls = Rc::clone(&discovery_calls);
            let discover = case["discover"].as_bool().unwrap_or(false);
            coordinator = coordinator.with_discovery(Box::new(move || {
                *calls.borrow_mut() += 1;
                if discover {
                    registry.lock().unwrap().register("i-1").unwrap();
                }
                discover
            }));
        }
        let result = coordinator.publish(
            &projection,
            generation,
            &fingerprint,
            terminate_keys.as_deref(),
        );
        let mut calls = writer_calls.borrow().clone();
        calls.extend(channel_calls.borrow().iter().cloned());
        assert_eq!(
            result.to_value(),
            case["result"],
            "case '{name}' result differs from Python"
        );
        assert_eq!(
            json!(calls),
            case["calls"],
            "case '{name}' calls differ from Python"
        );
        assert_eq!(
            *discovery_calls.borrow() as i64,
            case["discovery_calls"].as_i64().unwrap(),
            "case '{name}' discovery count differs from Python"
        );
    }
}

#[test]
fn terminate_keys_is_forwarded_only_when_present() {
    let projection = json!({
        "schema_version": 2,
        "config_generation": 4,
        "share_max_concurrency": 64,
        "data": [{
            "key_id": "k1", "name": "n1", "secret_hash": "a".repeat(64),
            "secret_version": 1, "enabled": true, "max_concurrency": 16,
        }],
    });
    let fingerprint = um_store::fingerprint(&projection);
    let registry = Arc::new(Mutex::new(InstanceRegistry::default()));
    registry.lock().unwrap().register("i-1").unwrap();
    let channel_calls = Rc::new(RefCell::new(Vec::new()));
    let responses = Rc::new(RefCell::new(vec![
        json!({"ok": true, "error_code": "ok", "result": {
            "instance_id": "i-1", "generation": 4, "fingerprint": fingerprint,
        }}),
        json!({"ok": true, "error_code": "ok", "result": {
            "instance_id": "i-1", "generation": 4, "fingerprint": fingerprint,
        }}),
    ]));
    let mut coordinator = PublishCoordinator::new(
        FakeWriter {
            calls: Rc::new(RefCell::new(Vec::new())),
            fail: false,
        },
        FakeChannel {
            calls: Rc::clone(&channel_calls),
            queue: Rc::clone(&responses),
            after_load: None,
        },
        Arc::clone(&registry),
    );
    let keys = vec!["k1".to_string(), "k2".to_string()];
    assert!(coordinator
        .publish(&projection, 4, &fingerprint, Some(&keys))
        .ok_flag());
    assert!(coordinator
        .publish(&projection, 4, &fingerprint, None)
        .ok_flag());
    let calls = channel_calls.borrow();
    assert_eq!(
        calls[0]["instance_call"]["fields"]["terminate_keys"],
        json!(["k1", "k2"])
    );
    assert!(calls[1]["instance_call"]["fields"]
        .get("terminate_keys")
        .is_none());
}

#[test]
fn a_refusal_is_never_a_fabricated_success() {
    let result = BrokerResult::err(ResultCode::FingerprintMismatch, "bad");
    assert!(!result.ok_flag());
    assert_eq!(result.error_code(), ResultCode::FingerprintMismatch);
}
